// the niches in three runs, each named by the niche it starts at
export const PACK_GROUPS = [
  { label: 'Use cases', from: 'status' },
  { label: 'Game genres', from: 'gaming' },
  { label: 'Interface', from: 'shapes' },
];

// a Fluent name as a key and a file name: no '!', '#' or accents, which a URL would read as syntax
export const packSlug = (name) => name.normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9_-]/g, '');

export const packKeys = (niche) => niche.fx.split(' ');

// every icon once, by key, as a path from this folder (parts.bdeb2397.js `asset` resolves FX paths against it)
export const PACK_FX = Object.fromEntries([...new Set(PACK.flatMap(packKeys))].map((key) => [key, `./fx/pack/${key}.png`]));
